// Calcula metricas acumuladas del embudo: deteccion -> match alto -> postulacion -> entrevista,
// mas si la HV adaptada por IA realmente correlaciona con mas entrevistas.
const rows = $input.all().map(i => i.json);
const total = rows.length;

const norm = (s) => String(s || '').trim().toLowerCase();
const estadoNorm = (r) => norm(r.estado);
const tieneHv = (r) => !!(r.hv_adaptada && String(r.hv_adaptada).trim());

const conMatch = rows.filter(r => r.match_pct !== undefined && r.match_pct !== '' && !isNaN(Number(r.match_pct)));
const altoMatch = conMatch.filter(r => Number(r.match_pct) >= 83);

const postuladas = rows.filter(r => estadoNorm(r) && estadoNorm(r) !== 'pendiente');
const entrevista = rows.filter(r => estadoNorm(r) === 'entrevista');
const descartado = rows.filter(r => estadoNorm(r) === 'descartado');

const altoMatchPostuladas = altoMatch.filter(r => estadoNorm(r) && estadoNorm(r) !== 'pendiente');

const conHv = rows.filter(tieneHv);
const conHvPostuladas = conHv.filter(r => estadoNorm(r) && estadoNorm(r) !== 'pendiente');
const conHvEntrevista = conHv.filter(r => estadoNorm(r) === 'entrevista');

const sinHvPostuladas = postuladas.filter(r => !tieneHv(r));
const sinHvEntrevista = sinHvPostuladas.filter(r => estadoNorm(r) === 'entrevista');

const pct = (num, den) => (den > 0 ? Math.round((num / den) * 1000) / 10 : null);

const avgMatch = (list) => {
  const vals = list.map((r) => Number(r.match_pct)).filter((n) => !isNaN(n));
  if (!vals.length) return null;
  return Math.round((vals.reduce((a, b) => a + b, 0) / vals.length) * 10) / 10;
};

const porFuente = {};
for (const r of rows) {
  const f = r.fuente || 'sin fuente';
  porFuente[f] = porFuente[f] || { total: 0, postuladas: 0 };
  porFuente[f].total++;
  if (estadoNorm(r) && estadoNorm(r) !== 'pendiente') porFuente[f].postuladas++;
}

return [{
  json: {
    total,
    conMatch: conMatch.length,
    altoMatch: altoMatch.length,
    postuladas: postuladas.length,
    entrevista: entrevista.length,
    descartado: descartado.length,
    conHv: conHv.length,
    tasaAltoMatchAPostulacion: pct(altoMatchPostuladas.length, altoMatch.length),
    tasaEntrevistaSobrePostuladas: pct(entrevista.length, postuladas.length),
    tasaEntrevistaConHv: pct(conHvEntrevista.length, conHvPostuladas.length),
    tasaEntrevistaSinHv: pct(sinHvEntrevista.length, sinHvPostuladas.length),
    promedioMatchGeneral: avgMatch(conMatch),
    promedioMatchEntrevista: avgMatch(entrevista),
    porFuente,
  },
}];

const m = $input.first().json;

const linea = (label, val, suf = '%') => (val === null || val === undefined ? `${label}: sin datos todavia` : `${label}: ${val}${suf}`);

let texto = `\ud83d\udcca *Metricas semanales \u2014 busqueda laboral*\n\n`;
texto += `Total ofertas en la planilla: ${m.total}\n`;
texto += `Con match calculado: ${m.conMatch} | Alto match (\u226583%): ${m.altoMatch}\n`;
texto += `Postuladas: ${m.postuladas} | En entrevista: ${m.entrevista} | Descartadas: ${m.descartado}\n\n`;

texto += `*Embudo*\n`;
texto += `${linea('Alto match \u2192 te postulaste', m.tasaAltoMatchAPostulacion)}\n`;
texto += `${linea('Postulacion \u2192 entrevista', m.tasaEntrevistaSobrePostuladas)}\n\n`;

texto += `*\u00bfEl match score predice bien?*\n`;
texto += `${linea('Match promedio (todas las scoreadas)', m.promedioMatchGeneral)}\n`;
texto += `${linea('Match promedio (las que llegaron a entrevista)', m.promedioMatchEntrevista)}\n\n`;

texto += `*\u00bfLa HV adaptada ayuda?*\n`;
texto += `HV generada en ${m.conHv} oferta(s)\n`;
texto += `${linea('Entrevista con HV adaptada', m.tasaEntrevistaConHv)}\n`;
texto += `${linea('Entrevista sin HV adaptada', m.tasaEntrevistaSinHv)}\n\n`;

const fuentes = Object.entries(m.porFuente || {});
if (fuentes.length) {
  texto += `*Por fuente*\n`;
  for (const [fuente, d] of fuentes) {
    texto += `${fuente}: ${d.total} detectadas, ${d.postuladas} postuladas\n`;
  }
}

return [{ json: { texto: texto.trim() } }];
